"""Shared plotting style. Every figure is generated by a script from results/*.csv."""
from __future__ import annotations

import matplotlib as mpl
import matplotlib.pyplot as plt

MODEL_COLORS = {
    "af3": "#1f77b4", "af3_no_template": "#7fb8dd", "boltz": "#d62728", "boltz1x": "#ff9896",
    "boltz2": "#8c564b", "chai": "#2ca02c", "protenix": "#9467bd", "rfaa": "#7f7f7f",
}
METHOD_COLORS = {"marginal": "#d62728", "mondrian": "#1f77b4", "weighted": "#2ca02c"}


def use_style() -> None:
    mpl.rcParams.update({
        "figure.dpi": 150, "savefig.dpi": 200, "savefig.bbox": "tight",
        "font.size": 9, "axes.titlesize": 10, "axes.labelsize": 9,
        "axes.spines.top": False, "axes.spines.right": False,
        "axes.grid": True, "grid.alpha": 0.25, "grid.linewidth": 0.5,
        "legend.frameon": False, "legend.fontsize": 8,
    })


def bin_order(bins) -> list:
    return sorted([b for b in bins if isinstance(b, str) and b != "all"], key=lambda b: float(b.split("-")[0]))
